class Solution:
    def longestConsecutive(self, nums: List[int]) -> int:
        num_set = set(nums)
        sz = 0
        for num in num_set:
            # 剪枝: 只判断连续序列的开头元素.
            if num - 1 in num_set:
                continue
            cur_sz = 1
            cur_num = num + 1
            while cur_num in num_set:
                cur_sz += 1
                cur_num += 1
            sz = max(sz, cur_sz)
        return sz
